import React from 'react';
import { Menu, Moon, Sun, Bell } from 'react-feather';

const Topbar = ({ currentUser, onMenu, onLogout, darkMode, onToggleTheme }) => (
  <header className="app-topbar">
    <button className="menu-toggle" onClick={onMenu} aria-label="Open navigation"><Menu size={21} /></button>
    <div className="topbar-context"><span>Employee portal</span><strong>Leave workspace</strong></div>
    <div className="topbar-actions">
      <button className="icon-button" aria-label="Notifications"><Bell size={18} /></button>
      <button className="icon-button" onClick={onToggleTheme} aria-label={darkMode ? 'Use light theme' : 'Use dark theme'}>
        {darkMode ? <Sun size={18} /> : <Moon size={18} />}
      </button>
      <div className="topbar-user" aria-label={`Signed in as ${currentUser?.name || 'employee'}`}>
        <span className="topbar-avatar">{(currentUser?.name || 'E').charAt(0).toUpperCase()}</span>
        <span className="topbar-user-name">{currentUser?.name || 'Employee'}</span>
      </div>
      <button className="sign-out-button" onClick={onLogout}>Sign out</button>
    </div>
  </header>
);

export default Topbar;
